import numpy as np

GRID_SIZE = 8

def check_2x2(grid, r, c):
    """
    Checks the 2x2 square starting at (r, c)
    Returns (num_infected, locations)
    """
    if r + 1 >= GRID_SIZE or c + 1 >= GRID_SIZE:
        return -1, [] # Out of bounds

    subgrid = grid[r:r+2, c:c+2]
    infected_count = np.sum(subgrid)
    locations = []
    for i in range(2):
        for j in range(2):
            if subgrid[i, j]:
                locations.append((r + i, c + j))
    return infected_count, locations

def simulate_step(grid):
    """
    Performs one step of growth and mutation based on the current grid state.
    Returns (new_grid, changes_made)
    """
    N = GRID_SIZE
    new_grid = np.copy(grid)

    infection_targets = set()  # Cells that will become infected by Rule 1
    mutation_regions = []     # (r, c) starting coordinates for Rule 2 mutation

    for r in range(N - 1):
        for c in range(N - 1):
            num_infected, infected_coords = check_2x2(grid, r, c)

            if num_infected == 3:
                # Rule 1: Spread (3I + 1S -> 4I)
                potential_cells = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
                sterile_cell = None
                for cell in potential_cells:
                    if cell not in infected_coords:
                        sterile_cell = cell
                        break

                if sterile_cell:
                    infection_targets.add(sterile_cell)

            elif num_infected == 2:
                # Rule 2: Mutation (2I + 2S -> 2S + 2I)
                mutation_regions.append((r, c))

    changes_made = False

    # Apply Rule 1 changes (Infection)
    for r, c in infection_targets:
        if not grid[r, c]: 
            new_grid[r, c] = True
            changes_made = True

    # Apply Rule 2 changes (Mutation)
